/** kebab-case-ish slug that keeps Korean characters; used in goal file names. */
export function slugify(title: string): string {
	return (
		title
			.trim()
			.toLowerCase()
			.replace(/[^\p{L}\p{N}]+/gu, "-")
			.replace(/^-+|-+$/g, "")
			.slice(0, 40)
			.replace(/-+$/g, "") || "goal"
	);
}

export interface NewGoalOptions {
