import { describe, expect, it } from "vitest";
import { goalAgeHours } from "../../src/features/goal-health";
import { goalTemplate } from "../../src/features/goals";
import { kstStamp, stampAgeHours } from "../../src/util/kst";
import { matchLine } from "../../src/util/markdown";

const NOW = Date.UTC(2026, 9, 5, 12, 0); // 2026-10-05 21:00 KST

/** The same instant (2026-10-05 03:00 UTC) written three ways; `마지막 갱신:` receives all three in practice. */
const UTC_Z = "2026-10-05T03:00:00Z";
const OFFSET = "2026-10-05T12:00:00+09:00";
const KST = "2026-10-05 12:00:00 KST";

describe("stamp age across timestamp notations", () => {
	it("reads Z, +09:00 and KST notations of one instant as the same age", () => {
		const z = goalAgeHours(goalTemplate(UTC_Z), NOW);
		const offset = goalAgeHours(goalTemplate(OFFSET), NOW);
		const kst = goalAgeHours(goalTemplate(KST), NOW);
		expect([z, offset, kst]).toEqual([9, 9, 9]);
	});

	it("honours a negative offset instead of assuming KST", () => {
		// 2026-10-04 23:00-04:00 is 2026-10-05 03:00 UTC — the same instant again.
		expect(goalAgeHours(goalTemplate("2026-10-04T23:00:00-04:00"), NOW)).toBe(9);
	});

	it("still reads an offset-less stamp as KST", () => {
		expect(goalAgeHours(goalTemplate(KST), NOW)).toBe(9);
		expect(stampAgeHours("2026-10-05 12:00", NOW)).toBe(9);
		// The format kstStamp() writes keeps its KST meaning.
		const human = kstStamp(new Date(Date.UTC(2026, 9, 5, 3, 0))).human;
		expect(stampAgeHours(human, NOW)).toBe(9);
	});

	it("agrees with the shared parser on every notation, so the stale-warning and auto-resume paths cannot diverge", () => {
		for (const stamp of [UTC_Z, OFFSET, KST, "no stamp", "2026-09-01"]) {
			const text = goalTemplate(stamp);
			const direct = stampAgeHours(matchLine(text, "마지막 갱신") || matchLine(text, "작성일"), NOW);
			expect(goalAgeHours(text, NOW)).toBe(direct);
		}
	});

	it("keeps Infinity for a missing or date-only stamp", () => {
		expect(goalAgeHours("no stamp", NOW)).toBe(Number.POSITIVE_INFINITY);
		expect(goalAgeHours(goalTemplate("2026-09-01"), NOW)).toBe(Number.POSITIVE_INFINITY);
		expect(stampAgeHours("", NOW)).toBe(Number.POSITIVE_INFINITY);
	});
});

}

function probeHost(hostName: string, port = 443, timeout = 2000): Promise<HostProbe> {
	return new Promise((resolve) => {
		try {
			const req = https.request({ host: hostName, port, method: "HEAD", timeout, path: "/" }, (res) => {
				resolve({ host: hostName, ok: true, status: res.statusCode });
				res.resume();
				req.destroy();
			});
			req.on("error", (error: NodeJS.ErrnoException) => resolve({ host: hostName, ok: false, err: error.code || error.message }));
			req.on("timeout", () => {
				resolve({ host: hostName, ok: false, err: "timeout" });
				req.destroy();
			});
			req.end();
		} catch (error) {
			resolve({ host: hostName, ok: false, err: String(error) });
		}
	});
}

