name: UI snapshots

# Screenshots of Vibe Code inside a real VS Code (serve-web + headless Chromium) for every pull
# request, in the dark and light themes, uploaded as the `ui-snapshots` artifact with an index.html
# contact sheet. A scene that cannot find its view or breaks an assertion (for example, the chat
# welcome view showing a validation error before anything was typed) fails the job.
# Run locally with `npm run snapshots` (scripts/ui-snapshots/run.mjs).
on:
  pull_request:
  workflow_dispatch:
    inputs:
      themes:
        description: Themes (dark, light, hc, hclight), comma-separated
        default: dark,light

permissions:
  contents: read

jobs:
  snapshots:
    name: UI snapshots
    runs-on: ubuntu-latest
    timeout-minutes: 40
    env:
      THEMES: ${{ inputs.themes || 'dark,light' }}
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-node@v4
        with:
          node-version: 20
          cache: npm
      - run: npm ci
      - run: npm run build

      - name: Restore runtime assets from the newest release VSIX
        shell: pwsh
        env:
          GH_TOKEN: ${{ github.token }}
        run: ./scripts/fetch-release-vsix.ps1

      # The runner has no Hangul font; without one every Korean label renders as boxes.
      - name: Korean fonts and Chromium
        run: |
          sudo apt-get update -qq
          sudo apt-get install -y -qq fonts-noto-cjk
          npx playwright install --with-deps chromium

      - name: Take snapshots
        run: |
          case "$THEMES" in *[!a-z,]*) echo "::error::themes must be a comma-separated list"; exit 1;; esac
          npm run snapshots -- --themes "$THEMES"

      - uses: actions/upload-artifact@v4
        if: always()
        with:
          name: ui-snapshots
          path: .tmp/ui-snapshots/out
          if-no-files-found: warn
          retention-days: 14
name: Release VSIX

# Every published release gets vibe-code-X.Y.Z.vsix and its .sha256 attached, built on Windows
# from the release's own tag. Releases are cut from environments without PowerShell, and
# v1.4.1-v1.4.6 went out with no package at all because nothing here did it for them.
#
# workflow_dispatch packages an existing tag (one cut before this workflow existed, or a retry).
# With upload off it only builds and keeps the VSIX as a workflow artifact.
on:
  release:
    types: [published]
  workflow_dispatch:
    inputs:
      tag:
        description: Release tag to package, e.g. v1.4.7
        required: true
      upload:
        description: Attach the VSIX to the release (off = build it as a workflow artifact only)
        type: boolean
        default: true

permissions:
  contents: read

concurrency:
  group: release-vsix-${{ github.event.release.tag_name || inputs.tag }}
  cancel-in-progress: false

jobs:
  plan:
    name: resolve release
    runs-on: ubuntu-latest
    outputs:
      tag: ${{ steps.resolve.outputs.tag }}
      version: ${{ steps.resolve.outputs.version }}
      vsix: ${{ steps.resolve.outputs.vsix }}
      upload: ${{ steps.resolve.outputs.upload }}
      build: ${{ steps.resolve.outputs.build }}
    steps:
      - id: resolve
        env:
          GH_TOKEN: ${{ github.token }}
          TAG: ${{ github.event.release.tag_name || inputs.tag }}
          UPLOAD: ${{ github.event_name == 'release' || inputs.upload }}
        run: |
          if [[ ! "$TAG" =~ ^v([0-9]+\.[0-9]+\.[0-9]+)$ ]]; then
            echo "::error::release tag must look like v1.2.3, got '$TAG'"
            exit 1
          fi
          version="${BASH_REMATCH[1]}"
          vsix="vibe-code-$version.vsix"
          assets=$(gh release view "$TAG" --repo "$GITHUB_REPOSITORY" --json assets --jq '.assets[].name')
          build=true
          if [[ "$UPLOAD" == "true" ]] && grep -qxF "$vsix" <<<"$assets"; then
            echo "::notice::$TAG already carries $vsix; nothing to do"
            build=false
          fi
          {
            echo "tag=$TAG"
            echo "version=$version"
            echo "vsix=$vsix"
            echo "upload=$UPLOAD"
            echo "build=$build"
          } >> "$GITHUB_OUTPUT"

  check:
    name: typecheck + unit tests + build (tag)
    needs: plan
    if: needs.plan.outputs.build == 'true'
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
        with:
          ref: refs/tags/${{ needs.plan.outputs.tag }}
      - uses: actions/setup-node@v4
        with:
          node-version: 20
          cache: npm
      - run: npm ci
      - run: npm run check

  vsix:
    name: package VSIX (windows)
    needs: plan
    if: needs.plan.outputs.build == 'true'
